import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Search, User, Menu, X, ArrowRight, Star } from 'lucide-react';

// --- COMPOSANTS ---

const Navbar = () => {
  const [isScrolled, setIsScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 50);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <nav className={`fixed w-full z-50 transition-all duration-500 ${isScrolled ? 'bg-white py-4 shadow-sm' : 'bg-transparent py-6'}`}>
      <div className="max-w-7xl mx-auto px-6 flex justify-between items-center">
        <h1 className={`text-2xl font-light tracking-[0.2em] uppercase ${isScrolled ? 'text-black' : 'text-white'}`}>
          Onyono
        </h1>
        
        <div className={`hidden md:flex space-x-8 text-xs uppercase tracking-widest ${isScrolled ? 'text-black' : 'text-white'}`}>
          <a href="#" className="hover:opacity-50 transition">Apprendre</a>
          <a href="#" className="hover:opacity-50 transition">Enseigner</a>
          <a href="#" className="hover:opacity-50 transition">À propos</a>
        </div>

        <div className={`flex items-center space-x-5 ${isScrolled ? 'text-black' : 'text-white'}`}>
          <Search size={20} strokeWidth={1.5} className="cursor-pointer" />
          <User size={20} strokeWidth={1.5} className="cursor-pointer" />
          <Menu size={20} strokeWidth={1.5} className="md:hidden cursor-pointer" />
        </div>
      </div>
    </nav>
  );
};

const TeacherCard = ({ name, subject, rating, image, price }) => (
  <motion.div 
    initial={{ opacity: 0, y: 20 }}
    whileInView={{ opacity: 1, y: 0 }}
    viewport={{ once: true }}
    className="group cursor-pointer"
  >
    <div className="relative overflow-hidden bg-[#F5F5F5] aspect-[3/4]">
      <img 
        src={image} 
        alt={name} 
        className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105"
      />
      <div className="absolute bottom-4 left-4 bg-white/90 backdrop-blur px-3 py-1 text-[10px] uppercase tracking-tighter">
        Nouveau
      </div>
    </div>
    <div className="mt-4 flex justify-between items-start">
      <div>
        <h3 className="text-sm font-medium tracking-wide uppercase">{name}</h3>
        <p className="text-gray-400 text-xs mt-1 italic">{subject}</p>
      </div>
      <div className="text-right">
        <p className="text-sm font-semibold">{price}€/h</p>
        <div className="flex items-center text-[10px] text-yellow-600 mt-1">
          <Star size={10} fill="currentColor" className="mr-1" /> {rating}
        </div>
      </div>
    </div>
  </motion.div>
);

const Hero = () => (
  <section className="relative h-screen flex items-center justify-center overflow-hidden bg-black">
    {/* Image de fond avec filtre sombre */}
    <div className="absolute inset-0 opacity-60">
      <img 
        src="https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&fit=crop&q=80" 
        className="w-full h-full object-cover"
        alt="Background"
      />
    </div>
    
    <div className="relative z-10 text-center px-4">
      <motion.span 
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 1 }}
        className="text-white text-xs uppercase tracking-[0.4em] mb-6 block"
      >
        L'excellence académique
      </motion.span>
      <motion.h2 
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 1, delay: 0.3 }}
        className="text-white text-4xl md:text-7xl font-light tracking-tight mb-10"
      >
        Apprenez sans <br /> compromis.
      </motion.h2>
      <motion.div 
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 1, delay: 0.8 }}
        className="flex flex-col md:flex-row gap-4 justify-center"
      >
        <button className="bg-white text-black px-10 py-4 text-xs uppercase tracking-widest hover:bg-black hover:text-white transition-all duration-500">
          Trouver un professeur
        </button>
        <button className="border border-white text-white px-10 py-4 text-xs uppercase tracking-widest hover:bg-white hover:text-black transition-all duration-500">
          Devenir enseignant
        </button>
      </motion.div>
    </div>
  </section>
);

// --- MAIN PAGE ---

export default function App() {
  const teachers = [
    { name: "Dr. Elena Rossi", subject: "Mathématiques avancées", price: "45", rating: "5.0", image: "https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?q=80&w=1000" },
    { name: "Marc-Antoine G.", subject: "Philosophie & Lettres", price: "35", rating: "4.9", image: "https://images.unsplash.com/photo-1560250097-0b93528c311a?q=80&w=1000" },
    { name: "Sophia Chen", subject: "Physique Quantique", price: "60", rating: "5.0", image: "https://images.unsplash.com/photo-1580489944761-15a19d654956?q=80&w=1000" },
